// Page de la salle de duel (générée depuis arena.html).
window.AR_PAGE = "<!doctype html>\n<html lang=\"fr\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width, initial-scale=1, viewport-fit=cover\">\n<title>Duel</title>\n<link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\n<link rel=\"preconnect\" href=\"https://fonts.gstatic.com\" crossorigin>\n<link href=\"https://fonts.googleapis.com/css2?family=Bagel+Fat+One&family=Inter:wght@400;600;800&display=swap\" rel=\"stylesheet\">\n<style>\n/* Layout : arène plein écran sur canvas, menus en surimpression, commandes tactiles en bas. Univers unique et sombre (arène nocturne sur gazon). */\n:root{\n  --bg:#080919; --panel:#121433; --panel2:#1a1d48; --line:#2e3275; --fg:#eef0ff; --mu:#9aa0d8;\n  --me:#3fd8ff; --op:#ff4fa3; --gold:#ffcf4a;\n  --font-d:'Bagel Fat One',system-ui,sans-serif; --font-b:Inter,system-ui,-apple-system,sans-serif;\n  color-scheme:dark;\n}\n[hidden]{display:none!important}\nhtml,body{height:100%;margin:0}\n*{box-sizing:border-box;margin:0}\n.vs{display:grid;grid-template-columns:1fr auto 1fr;gap:12px;align-items:center}\n.side{display:flex;align-items:center;gap:10px;background:var(--panel2);border-radius:14px;padding:10px 12px;min-width:0}\n.side b{display:block;font-size:16px}\n.side small{color:var(--mu);font-size:12px}\n.vsx{font-family:var(--font-d);color:var(--mu);font-size:18px}\n@media (max-width:520px){.vs{grid-template-columns:1fr}.vsx{text-align:center}}\nbody{background:var(--bg);color:var(--fg);font-family:var(--font-b);overflow:hidden;touch-action:none;user-select:none;-webkit-user-select:none}\n#cv{position:fixed;inset:0;display:block}\n.ov{position:fixed;inset:0;display:flex;align-items:flex-start;justify-content:center;background:color-mix(in srgb,var(--bg) 62%,transparent);\n  padding-left:max(16px,env(safe-area-inset-left,0px));padding-right:max(16px,env(safe-area-inset-right,0px));padding-block:calc(16px + env(safe-area-inset-top,0px)) calc(16px + env(safe-area-inset-bottom,0px));overflow:auto;z-index:5}\n.box{width:100%;max-width:780px;background:color-mix(in srgb,var(--panel) 92%,transparent);border:1.5px solid var(--line);border-radius:20px;padding:22px;display:flex;flex-direction:column;gap:14px;margin:auto;box-shadow:0 30px 80px #0009}\nh1{font-family:var(--font-d);font-weight:400;font-size:clamp(34px,6vw,56px);line-height:1;text-wrap:balance}\nh1 span{color:var(--op)}\n.tag{color:var(--mu);font-weight:600;margin-top:-6px}\nh2{font-size:12px;letter-spacing:.14em;text-transform:uppercase;color:var(--mu);font-weight:800}\n.opts{display:grid;grid-template-columns:repeat(auto-fit,minmax(190px,1fr));gap:10px}\n.opts.row{grid-template-columns:repeat(3,1fr)}\n.op{background:var(--panel2);border:2px solid var(--line);border-radius:14px;color:var(--fg);padding:12px 14px;text-align:left;font:inherit;cursor:pointer;display:flex;flex-direction:column;gap:4px;min-width:0}\n.op b{font-size:16px}\n.op small{color:var(--mu);font-size:13px;line-height:1.35}\n.op.on{border-color:var(--me);background:color-mix(in srgb,var(--me) 14%,var(--panel2))}\n.opts.row .op{text-align:center;align-items:center}\n.teams{display:grid;grid-template-columns:repeat(auto-fit,minmax(240px,1fr));gap:12px}\n.teams h2{margin-bottom:8px}\n.cyc{display:flex;align-items:center;gap:8px;background:var(--panel2);border:2px solid var(--line);border-radius:14px;padding:8px;outline:none}\n.cyc:focus-visible,.cyc.kf{border-color:var(--gold)}\n.cyc .ar{font:800 22px var(--font-b);width:40px;height:40px;border-radius:10px;border:1.5px solid var(--line);background:var(--panel);color:var(--fg);cursor:pointer;flex:none}\n.cyc .cv{flex:1;display:flex;align-items:center;gap:10px;min-width:0}\n.cyc .cv b{font-size:17px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}\n.sw{width:30px;height:30px;border-radius:8px;flex:none;border:1.5px solid #ffffff55}\n.btn{font:inherit;font-weight:800;font-size:18px;border-radius:14px;border:2px solid var(--line);background:var(--panel2);color:var(--fg);padding:12px 18px;cursor:pointer}\n.btn.big{background:var(--op);border-color:var(--op);color:#fff;font-size:22px;padding:14px}\n.btns{display:flex;gap:10px;flex-wrap:wrap}\n.btns .btn{flex:1 1 160px}\n.op:focus-visible,.btn:focus-visible,.kf{outline:3px solid var(--gold)!important;outline-offset:2px}\n.ctl{display:grid;grid-template-columns:repeat(auto-fit,minmax(210px,1fr));gap:10px}\n.ctl div{background:var(--panel2);border-radius:12px;padding:10px 12px;font-size:13px;line-height:1.55;min-width:0}\n.ctl b{display:block;font-size:12px;letter-spacing:.12em;text-transform:uppercase;color:var(--gold);margin-bottom:4px}\nkbd{font:inherit;font-weight:800;background:#ffffff14;border:1px solid #ffffff2a;border-radius:6px;padding:0 5px}\n#padst{font-size:13px;color:var(--mu)}\n#padst.ok{color:var(--me);font-weight:700}\n.stats{display:grid;grid-template-columns:1fr auto auto;gap:6px 18px;font-variant-numeric:tabular-nums}\n.stats .h{color:var(--mu);font-size:12px;text-transform:uppercase;letter-spacing:.1em}\n.res{font-family:var(--font-d);font-size:clamp(30px,6vw,48px);line-height:1}\n/* Tactile */\n#touch{position:fixed;inset:0;z-index:3;pointer-events:none}\n#jz{position:absolute;left:0;bottom:0;width:50%;height:65%;pointer-events:auto}\n#joy{position:absolute;width:120px;height:120px;border-radius:50%;border:2px solid #ffffff30;background:#ffffff0c;transform:translate(-50%,-50%);display:none}\n#knob{position:absolute;left:50%;top:50%;width:54px;height:54px;margin:-27px;border-radius:50%;background:#ffffff40}\n.tb{position:absolute;pointer-events:auto;border-radius:50%;border:2px solid #ffffff40;background:#ffffff14;color:var(--fg);font:800 13px var(--font-b);display:flex;flex-direction:column;align-items:center;justify-content:center;gap:2px;touch-action:none}\n.tb small{font-weight:600;font-size:10px;color:var(--mu)}\n.tb.dn{background:#ffffff33}\n#bShoot{width:96px;height:96px;right:calc(28px + env(safe-area-inset-right,0px));bottom:calc(40px + env(safe-area-inset-bottom,0px));border-color:var(--op)}\n#bFeint{width:66px;height:66px;right:calc(136px + env(safe-area-inset-right,0px));bottom:calc(30px + env(safe-area-inset-bottom,0px))}\n#bLob{width:66px;height:66px;right:calc(130px + env(safe-area-inset-right,0px));bottom:calc(112px + env(safe-area-inset-bottom,0px))}\n#bSprint{width:66px;height:66px;right:calc(40px + env(safe-area-inset-right,0px));bottom:calc(150px + env(safe-area-inset-bottom,0px))}\n#bPause{position:fixed;z-index:4;top:calc(12px + env(safe-area-inset-top,0px));right:calc(12px + env(safe-area-inset-right,0px));width:40px;height:40px;border-radius:12px;border:1.5px solid var(--line);background:var(--panel);color:var(--fg);font:800 16px var(--font-b);cursor:pointer}\n</style>\n\n</head><body>\n<canvas id=\"cv\"></canvas>\n<button id=\"bPause\" hidden aria-label=\"Pause\">II</button>\n\n<div id=\"touch\" hidden>\n  <div id=\"jz\"><div id=\"joy\"><div id=\"knob\"></div></div></div>\n  <div class=\"tb\" id=\"bShoot\"><span id=\"bShootL\">TIR</span><small>glisser = effet</small></div>\n  <div class=\"tb\" id=\"bLob\">LOB</div>\n  <div class=\"tb\" id=\"bFeint\">CROCHET</div>\n  <div class=\"tb\" id=\"bSprint\">SPRINT</div>\n</div>\n\n<div class=\"ov\" id=\"menu\">\n  <div class=\"box\">\n    <h1 id=\"mT\"></h1>\n    <p class=\"tag\" id=\"mSub\"></p>\n    <div class=\"vs\">\n      <div class=\"side\"><span class=\"sw\" id=\"swMe\"></span><div><b id=\"nMe\"></b><small id=\"sMe\"></small></div></div>\n      <div class=\"vsx\">contre</div>\n      <div class=\"side\"><span class=\"sw\" id=\"swOp\"></span><div><b id=\"nOp\"></b><small id=\"sOp\"></small></div></div>\n    </div>\n    <button class=\"btn big\" id=\"play\" data-nav>Entrer dans la salle</button>\n    <p id=\"padst\">Branche une manette et appuie sur un de ses boutons pour la détecter.</p>\n    <div class=\"ctl\">\n      <div><b>Manette</b>Stick gauche : courir et viser<br><kbd>A</kbd> avec la balle : maintenir pour charger, relâcher pour tirer<br><kbd>A</kbd> sans la balle : tacle glissé<br><kbd>Y</kbd> : lob (maintenir pour doser)<br><kbd>B</kbd> / <kbd>X</kbd> : crochet<br>Gâchettes : sprint<br>Stick droit pendant la charge : effet<br><kbd>Start</kbd> : pause</div>\n      <div><b>Clavier</b><kbd>ZQSD</kbd> / <kbd>WASD</kbd> / flèches : courir et viser<br><kbd>Espace</kbd> : tir (maintenir) ou tacle glissé<br><kbd>I</kbd> : lob<br><kbd>K</kbd> : crochet<br><kbd>Maj</kbd> : sprint<br><kbd>J</kbd> / <kbd>L</kbd> pendant la charge : effet<br><kbd>Échap</kbd> : pause</div>\n      <div><b>Tactile</b>Joystick à gauche : courir et viser<br>TIR : maintenir puis relâcher, glisser le doigt pour l’effet ; devient TACLE sans la balle<br>LOB, CROCHET et SPRINT à droite</div>\n    </div>\n    <p class=\"tag\" style=\"margin:0;font-size:13px;line-height:1.5\">Premier à 3 buts. Marque dans le trou <b style=\"color:var(--me)\">cyan</b>, défends le trou <b style=\"color:var(--op)\">rose</b>. La balle rebondit sur les quatre murs et le plafond. Tout est permis : Un tacle qui fauche le joueur le met au sol et libère la balle. Des obstacles surgissent du sol en cours de match.</p>\n  </div>\n</div>\n\n<div class=\"ov\" id=\"pause\" hidden>\n  <div class=\"box\" style=\"max-width:420px\">\n    <h1>Pause</h1>\n    <div class=\"btns\" style=\"flex-direction:column\">\n      <button class=\"btn big\" id=\"resume\" data-nav>Reprendre</button>\n      <button class=\"btn\" id=\"forfeit\" data-nav>Abandonner le duel</button>\n    </div>\n  </div>\n</div>\n\n<div class=\"ov\" id=\"end\" hidden>\n  <div class=\"box\" style=\"max-width:480px\">\n    <div class=\"res\" id=\"endT\">Victoire</div>\n    <div id=\"endS\" style=\"font-weight:800;font-size:22px\"></div>\n    <div class=\"stats\" id=\"endStats\"></div>\n    <div class=\"btns\">\n      <button class=\"btn big\" id=\"again\" data-nav>Continuer</button>\n    </div>\n  </div>\n</div>\n\n<script>\n(()=>{\n'use strict';\n// ---------- Réglages ----------\nconst HX=300, HY=212, PR=15, BR=7, HOLER=27, HOLEC=20, CEIL=130, STEP=1/120, ROUND=12, PEN_T=5, WIN=3, CATCH=380, CROSS=38, SLIDE_T=.42, SLIDE_V=480;\nconst ME='#3fd8ff', OP='#ff4fa3', GOLD='#ffcf4a';\nconst hex2=h=>[1,3,5].map(i=>parseInt(h.slice(i,i+2),16));\nconst lum=h=>{const [r,g,b]=hex2(h);return(.2126*r+.7152*g+.0722*b)/255};\nconst shade=(h,k)=>'#'+hex2(h).map(v=>Math.round(k<0?v*(1+k):v+(255-v)*k).toString(16).padStart(2,'0')).join('');\nfunction mkKit(name,shirt,acc,skin,hair,num){\n  const pants=lum(shirt)<.12?shirt:shade(shirt,lum(shirt)>.8?-.6:-.5);\n  return{team:name,shirt,shirt2:acc,sleeve:acc,shorts:pants,socks:pants,boots:lum(acc)>.85?'#222':acc,skin,hair,num};\n}\nlet KIT=[];\n// Réglages envoyés par la carrière (joueur choisi, adversaire, tour du tournoi)\nconst H=(()=>{try{return window.parent&&window.parent.ARH}catch(e){return null}})();\nlet SET=null,AIP=null,MY={sh:1,tk:1,sp:1};\nfunction loadSetup(){\n  SET=(H&&H.setup&&H.setup())||{title:'Duel',round:'Duel',me:{n:'Joueur',club:'Club',a:'#3f6fd8',b:'#ffffff',att:70,def:70,en:100,num:10},op:{n:'Adversaire',lvl:70,a:'#d9327f',b:'#1b0b18',num:9}};\n  const L=clamp((SET.op.lvl-50)/45,0,1),lerp=(x,y)=>x+(y-x)*L;\n  AIP={spd:lerp(.8,1.02),react:lerp(.42,.14),tack:lerp(.55,1.7),aim:lerp(.09,.015),bite:lerp(.75,.25),think:lerp(1,.3),feint:lerp(.15,.65)};\n  const a=clamp((SET.me.att-50)/45,0,1),d=clamp((SET.me.def-50)/45,0,1);\n  MY={sh:.9+.2*a,tk:.9+.2*d,sp:.95+.1*(a+d)/2};\n}\n// ---------- Canvas ----------\nconst cv=document.getElementById('cv'), cx=cv.getContext('2d');\nlet W=0,HH=0,DPR=1;\nfunction resize(){DPR=Math.min(2,window.devicePixelRatio||1);W=innerWidth;HH=innerHeight;cv.width=Math.round(W*DPR);cv.height=Math.round(HH*DPR);cv.style.width=W+'px';cv.style.height=HH+'px'}\naddEventListener('resize',resize);resize();\nconst STARS=[...Array(140)].map(()=>[Math.random(),Math.random(),Math.random()*1.4+.3,Math.random()*6]);\n\n// ---------- Outils ----------\nconst len=(x,y)=>Math.hypot(x,y);\nconst clamp=(v,a,b)=>v<a?a:v>b?b:v;\nconst angD=(a,b)=>{let d=a-b;while(d>Math.PI)d-=2*Math.PI;while(d<-Math.PI)d+=2*Math.PI;return d};\nlet MODE=0,OBS=[];const OH=70;\n// point le plus proche d'un obstacle\nfunction obsNear(o,x,y){if(o.type=='pil'){const dx=x-o.x,dy=y-o.y,d=len(dx,dy)||1;return[o.x+dx/d*o.r,o.y+dy/d*o.r,d<o.r]}return[clamp(x,o.x-o.w,o.x+o.w),clamp(y,o.y-o.h,o.y+o.h),Math.abs(x-o.x)<o.w&&Math.abs(y-o.y)<o.h]}\n// repousse un disque (rayon r) hors des obstacles levés ; renvoie la normale du contact\nfunction pushOut(e,r){let hit=null;for(const o of OBS){if(o.k<.5)continue;const q=obsNear(o,e.x,e.y);let nx=e.x-q[0],ny=e.y-q[1],d=len(nx,ny);\n  if(q[2]){if(o.type=='pil'){nx=e.x-o.x;ny=e.y-o.y;d=len(nx,ny)||1;nx/=d;ny/=d;e.x=o.x+nx*(o.r+r);e.y=o.y+ny*(o.r+r)}else{const px=o.w-Math.abs(e.x-o.x),py=o.h-Math.abs(e.y-o.y);if(px<py){nx=Math.sign(e.x-o.x)||1;ny=0;e.x=o.x+nx*(o.w+r)}else{nx=0;ny=Math.sign(e.y-o.y)||1;e.y=o.y+ny*(o.h+r)}}hit=[nx,ny]}\n  else if(d<r){nx/=d;ny/=d;e.x=q[0]+nx*r;e.y=q[1]+ny*r;hit=[nx,ny]}}return hit}\nfunction holeY(i,t){return MODE==2?Math.sin(t*.35)*(HY-70)*(i==0?1:-1):0}\nfunction holePos(i,t){return[i==0?HX:-HX,holeY(i,t)]}\nfunction grav(t){if(MODE!=1)return null;const a=t*0.45;return[Math.cos(a)*150,Math.sin(a)*150]}\n\n// Physique de la balle (jeu, aperçu de trajectoire et IA) ; z = hauteur\nfunction ballMove(b,dt,t){\n  const g=grav(t);if(g&&b.z<1){b.vx+=g[0]*dt;b.vy+=g[1]*dt}\n  if(b.spin){const a=b.spin*dt,c=Math.cos(a),s=Math.sin(a),vx=b.vx*c-b.vy*s;b.vy=b.vx*s+b.vy*c;b.vx=vx;b.spin*=Math.exp(-1.1*dt);if(Math.abs(b.spin)<.01)b.spin=0}\n  const air=b.z>.5,f=Math.exp((air?-.1:-.38)*dt);b.vx*=f;b.vy*=f;\n  if(air||b.vz>0){b.vz-=640*dt;b.z+=b.vz*dt;if(b.z<=0){b.z=0;b.vz=b.vz<-80?-b.vz*.42:0}}\n  b.x+=b.vx*dt;b.y+=b.vy*dt;b.bounced=0;b.bar=0;\n  if(b.z>CEIL){b.z=CEIL;b.vz=-Math.abs(b.vz)*.6}\n  if(Math.abs(b.x)>HX-BR){\n    const i=b.x>0?0:1,sg=b.x>0?1:-1,dy=Math.abs(b.y-holeY(i,t));\n    if(dy<HOLER){if(len(dy,b.z+BR-HOLEC)<HOLER-BR*.4)return i;if(b.z>HOLEC)b.bar=1}\n    if(b.vx*sg>0){b.bounced=Math.abs(b.vx);b.vx=-b.vx*.85;b.spin*=.5}\n    b.x=sg*(HX-BR);\n  }\n  if(Math.abs(b.y)>HY-BR){const sg=b.y>0?1:-1;if(b.vy*sg>0){b.bounced=Math.max(b.bounced,Math.abs(b.vy));b.vy=-b.vy*.85;b.spin*=.5}b.y=sg*(HY-BR)}\n  if(OBS.length&&b.z<OH){const n=pushOut(b,BR);if(n){const vn=b.vx*n[0]+b.vy*n[1];if(vn<0){b.vx-=1.85*vn*n[0];b.vy-=1.85*vn*n[1];b.spin*=.5;b.bounced=Math.max(b.bounced,-vn)}}}\n  return -1;\n}\nfunction simPath(x,y,vx,vy,spin,z,vz,t0,T,av,pts){\n  const b={x,y,vx,vy,spin,z,vz};let clear=1e9;const st=1/60;\n  for(let t=0;t<T;t+=st){\n    const r=ballMove(b,st,t0+t);\n    if(av&&t<.7&&b.z<18){const dd=len(b.x-av.x,b.y-av.y);if(dd<clear)clear=dd}\n    if(pts)pts.push(b.x,b.y,b.z);\n    if(r>=0)return{goal:r,t,clear};\n    if(len(b.vx,b.vy)<110&&b.z<1)break;\n  }\n  return{goal:-1,t:T,clear};\n}\n\n// ---------- Son ----------\nlet AC=null;\nfunction initAudio(){if(AC)return;try{AC=new(window.AudioContext||window.webkitAudioContext)()}catch(e){}}\naddEventListener('pointerdown',initAudio);addEventListener('keydown',initAudio);\nconst SFX={kick:[240,.09,'square',.07],lob:[380,.12,'sine',.06],catch:[540,.05,'sine',.05],block:[150,.12,'sawtooth',.07],slide:[110,.25,'sawtooth',.05],steal:[95,.2,'sawtooth',.1],goal:[620,.6,'triangle',.13],wall:[190,.05,'sine',.04],jink:[460,.05,'triangle',.04],whistle:[2100,.35,'sine',.06],rise:[70,.45,'sawtooth',.09],bar:[880,.3,'square',.05]};\nfunction sfx(k){try{if(!AC)return;const p=SFX[k],T=AC.currentTime,o=AC.createOscillator(),g=AC.createGain();o.type=p[2];o.frequency.setValueAtTime(p[0],T);\n  if(k=='goal')o.frequency.exponentialRampToValueAtTime(1240,T+.45);if(k=='steal'||k=='slide'||k=='rise')o.frequency.exponentialRampToValueAtTime(45,T+p[1]);if(k=='whistle'){o.frequency.setValueAtTime(2300,T+.12);o.frequency.setValueAtTime(2100,T+.2)}\n  g.gain.setValueAtTime(p[3],T);g.gain.exponentialRampToValueAtTime(.0001,T+p[1]);o.connect(g).connect(AC.destination);o.start(T);o.stop(T+p[1]+.02)}catch(e){}}\n\n// ---------- Manette ----------\nlet padName='';\nfunction pad(){let ps=[];try{ps=navigator.getGamepads?navigator.getGamepads():[]}catch(e){}for(const p of ps||[])if(p&&p.connected)return p;return null}\nfunction rumble(ms,s,w){const gp=pad();try{gp&&gp.vibrationActuator&&gp.vibrationActuator.playEffect('dual-rumble',{duration:ms,strongMagnitude:s,weakMagnitude:w})}catch(e){}}\naddEventListener('gamepadconnected',e=>{padName=e.gamepad.id;updPad()});\naddEventListener('gamepaddisconnected',()=>{padName=pad()?pad().id:'';updPad()});\nfunction updPad(){const el=document.getElementById('padst');if(padName){el.textContent='Manette détectée : '+padName.replace(/\\(.*?\\)/g,'').trim().slice(0,60);el.className='ok'}else{el.textContent='Branche une manette et appuie sur un de ses boutons pour la détecter.';el.className=''}}\nconst dz=v=>Math.abs(v)<.2?0:(v-Math.sign(v)*.2)/.8;\n\n// ---------- Entrées ----------\nconst keys=new Set();let lastDev='kb';\naddEventListener('keydown',e=>{keys.add(e.code);lastDev='kb';if(state=='play'&&['Space','ArrowUp','ArrowDown','ArrowLeft','ArrowRight'].includes(e.code))e.preventDefault()});\naddEventListener('keyup',e=>keys.delete(e.code));\naddEventListener('blur',()=>keys.clear());\nconst T={mx:0,my:0,shoot:false,lob:false,sprint:false,feint:false,curve:0,on:false};\nlet prevB={},IN={mx:0,my:0,sprint:false,curve:0};\nfunction readInput(){\n  let mx=0,my=0,sprint=false,shoot=false,lob=false,feint=false,curve=0,pause=false,back=false,pok=false;\n  if(keys.has('KeyA')||keys.has('ArrowLeft'))mx-=1;if(keys.has('KeyD')||keys.has('ArrowRight'))mx+=1;\n  if(keys.has('KeyW')||keys.has('ArrowUp'))my-=1;if(keys.has('KeyS')||keys.has('ArrowDown'))my+=1;\n  sprint=keys.has('ShiftLeft')||keys.has('ShiftRight');shoot=keys.has('Space');lob=keys.has('KeyI');feint=keys.has('KeyK');\n  if(keys.has('KeyJ'))curve-=1;if(keys.has('KeyL'))curve+=1;\n  pause=keys.has('Escape')||keys.has('KeyP');\n  const gp=pad();\n  if(gp){\n    const bt=i=>!!(gp.buttons[i]&&(gp.buttons[i].pressed||gp.buttons[i].value>.4));\n    const ax=dz(gp.axes[0]||0),ay=dz(gp.axes[1]||0);mx+=ax;my+=ay;\n    if(bt(14))mx-=1;if(bt(15))mx+=1;if(bt(12))my-=1;if(bt(13))my+=1;\n    if(gp.buttons.some(b=>b.pressed)||Math.abs(ax)+Math.abs(ay)>0){lastDev='pad';if(!padName){padName=gp.id;updPad()}}\n    shoot=shoot||bt(0);lob=lob||bt(3);feint=feint||bt(1)||bt(2);sprint=sprint||bt(4)||bt(5)||bt(6)||bt(7);\n    curve+=dz(gp.axes[2]||0);pause=pause||bt(9);pok=bt(0);back=bt(1);\n  }\n  mx+=T.mx;my+=T.my;shoot=shoot||T.shoot;lob=lob||T.lob;sprint=sprint||T.sprint;feint=feint||T.feint;T.feint=false;curve+=T.curve;\n  const m=len(mx,my);if(m>1){mx/=m;my/=m}\n  curve=clamp(curve,-1,1);\n  const cur={shoot,lob,feint,pause,pok,back,up:my<-.55,down:my>.55,left:mx<-.55,right:mx>.55};\n  const e=k=>cur[k]&&!prevB[k];\n  IN={mx,my,sprint,curve,shootDown:e('shoot'),shootUp:!shoot&&!!prevB.shoot,lobDown:e('lob'),lobUp:!lob&&!!prevB.lob,feintDown:e('feint'),pauseDown:e('pause'),okDown:e('pok'),backDown:e('back'),\n      nav:e('up')?-1:e('down')?1:0,hnav:e('left')?-1:e('right')?1:0};\n  prevB=cur;\n}\n\n// Tactile\nconst touchEl=document.getElementById('touch'),jz=document.getElementById('jz'),joy=document.getElementById('joy'),knob=document.getElementById('knob');\nlet jId=null,j0=[0,0];\nfunction showTouch(){if(!T.on){T.on=true;if(state=='play')touchEl.hidden=false}}\nif(matchMedia('(pointer:coarse)').matches)T.on=true;\naddEventListener('pointerdown',e=>{if(e.pointerType=='touch'){lastDev='touch';showTouch()}},true);\njz.addEventListener('pointerdown',e=>{jId=e.pointerId;j0=[e.clientX,e.clientY];joy.style.display='block';joy.style.left=e.clientX+'px';joy.style.top=e.clientY+'px';knob.style.transform='';jz.setPointerCapture(e.pointerId)});\njz.addEventListener('pointermove',e=>{if(e.pointerId!==jId)return;let dx=e.clientX-j0[0],dy=e.clientY-j0[1];const l=len(dx,dy),mx=50;if(l>mx){dx*=mx/l;dy*=mx/l}knob.style.transform=`translate(${dx}px,${dy}px)`;T.mx=dx/mx;T.my=dy/mx});\nconst jEnd=e=>{if(e.pointerId!==jId)return;jId=null;T.mx=T.my=0;joy.style.display='none'};\njz.addEventListener('pointerup',jEnd);jz.addEventListener('pointercancel',jEnd);\nfunction tbtn(id,down,up,move){const el=document.getElementById(id);let pid=null,x0=0;\n  el.addEventListener('pointerdown',e=>{pid=e.pointerId;x0=e.clientX;el.setPointerCapture(pid);el.classList.add('dn');down()});\n  el.addEventListener('pointermove',e=>{if(e.pointerId===pid&&move)move(e.clientX-x0)});\n  const u=e=>{if(e.pointerId!==pid)return;pid=null;el.classList.remove('dn');up&&up()};\n  el.addEventListener('pointerup',u);el.addEventListener('pointercancel',u)}\ntbtn('bShoot',()=>{T.shoot=true;T.curve=0},()=>{T.shoot=false},dx=>{T.curve=clamp(dx/60,-1,1)});\ntbtn('bLob',()=>{T.lob=true},()=>{T.lob=false});\ntbtn('bSprint',()=>{T.sprint=true},()=>{T.sprint=false});\ntbtn('bFeint',()=>{T.feint=true},null);\nconst bShootL=document.getElementById('bShootL');\n\n// ---------- Partie ----------\nlet G=null,state='menu';\nfunction mkP(i){return{i,x:0,y:0,vx:0,vy:0,fx:i?-1:1,fy:0,en:100,has:0,charging:0,ctype:'shot',charge:0,slideT:0,sdx:0,sdy:0,hitBall:0,fouled:0,stun:0,pose:'',jinkT:0,jinkCd:0,jx:0,jy:0,ph:0,fouls:0,yellow:0,dust:0}}\nfunction newMatch(){\n  MODE=0;OBS=[];\n  KIT=[mkKit(SET.me.club,SET.me.a,SET.me.b,'#d9a27a','#3a2a1a',SET.me.num),mkKit(SET.op.n,SET.op.a,SET.op.b,'#8c5a3c','#1a1210',SET.op.num)];\n  G={obsOn:true,obs:OBS,obsT:7+Math.random()*4,t:0,score:[0,0],round:0,att:Math.random()<.5?0:1,phase:'ready',pt:0,rt:ROUND,P:[mkP(0),mkP(1)],pen:null,next:null,\n     ball:{x:0,y:0,z:0,vx:0,vy:0,vz:0,spin:0,rot:0,owner:-1,last:-1,nc:0,ncw:-1,trail:[],gone:0,bt:0},fx:[],shake:0,msg:'',msgT:0,slow:0,\n     res:null,stats:{shots:[0,0],lobs:[0,0],saves:[0,0],tackles:[0,0],fouls:[0,0],jinks:[0,0]}};\n  G.P[0].en=clamp(SET.me.en,30,100);\n  startRound(false);\n}\nfunction attach(p){const b=G.ball,o=PR+BR+1+3*Math.abs(Math.sin(p.ph));b.x=p.x+p.fx*o;b.y=p.y+p.fy*o;b.z=0;b.vz=0;b.x=clamp(b.x,-HX+BR,HX-BR);b.y=clamp(b.y,-HY+BR,HY-BR);pushOut(b,BR)}\nfunction startRound(pen){\n  const a=G.att,P=G.P,b=G.ball;G.round++;\n  for(const p of P){p.vx=p.vy=0;p.has=0;p.charging=0;p.charge=0;p.slideT=0;p.stun=0;p.pose='';p.jinkT=0;p.en=Math.min(100,p.en+12)}\n  const A=P[a],D=P[1-a];\n  for(const o of G.obs)if(o.st!='down'&&len(o.x,o.y)<(o.type=='pil'?o.r:Math.max(o.w,o.h))+140){o.st='down';o.t=0}\n  if(pen){\n    const sg=a==0?1:-1;\n    A.x=0;A.y=0;A.fx=sg;A.fy=0;D.x=sg*(HX-30);D.y=0;D.fx=-sg;D.fy=0;\n    G.pen={k:D.i,mx:D.x,my:D.y};G.rt=PEN_T;G.msg='Penalty : tir depuis le centre';\n  }else{\n    const sg=a==0?1:-1;A.x=0;A.y=0;A.fx=sg;A.fy=0;D.x=sg*95;D.y=0;D.fx=-sg;D.fy=0;\n    G.pen=null;G.rt=ROUND;G.msg=a==0?'À toi d’attaquer':'L’adversaire attaque';\n  }\n  A.has=1;b.owner=a;b.last=a;b.vx=b.vy=b.vz=b.z=0;b.spin=0;b.gone=0;b.trail.length=0;b.nc=0;attach(A);\n  G.phase='ready';G.pt=1.1;G.msgT=1.1;\n  AI.reset(a==1);\n}\nfunction startCharge(p,type){if(p.has&&!p.charging&&p.stun<=0){p.charging=1;p.ctype=type;p.charge=0}}\nfunction release(p,curve){\n  const b=G.ball;if(!p.has)return;\n  const c=Math.max(.12,p.charge),ef=.7+.3*Math.min(1,p.en/30);\n  p.has=0;p.charging=0;p.charge=0;attach(p);b.owner=-1;b.last=p.i;b.nc=.25;b.ncw=p.i;G.pen=null;\n  if(p.ctype=='lob'){\n    const hs=(230+230*c)*ef;b.vx=p.fx*hs+p.vx*.2;b.vy=p.fy*hs+p.vy*.2;b.vz=230+170*c;b.z=1;b.spin=curve*1.2;\n    p.en=Math.max(0,p.en-(5+10*c));G.stats.lobs[p.i]++;sfx('lob');\n  }else{\n    const sp=(330+600*c)*ef*(p.i==0?MY.sh:1);b.vx=p.fx*sp+p.vx*.25;b.vy=p.fy*sp+p.vy*.25;b.vz=c>.8?60:0;b.z=c>.8?1:0;b.spin=curve*2.6;\n    p.en=Math.max(0,p.en-(6+16*c));G.stats.shots[p.i]++;sfx('kick');\n  }\n  p.kickT=.18;\n  if(p.i==0){AI.onShot();rumble(80,.15+.5*c,.3)}\n}\nfunction jink(p,dx,dy){\n  if(!p.has||p.jinkCd>0||p.stun>0||p.charging)return;\n  let m=len(dx,dy);if(m<.3){const s=Math.random()<.5?1:-1;dx=-p.fy*s;dy=p.fx*s;m=1}\n  p.jx=dx/m*400;p.jy=dy/m*400;p.jinkT=.16;p.jinkCd=.6;p.en=Math.max(0,p.en-5);G.stats.jinks[p.i]++;sfx('jink');\n  if(p.i==0){AI.onFeint();rumble(60,0,.4)}\n}\nfunction tackle(p,dx,dy){\n  if(p.has||p.slideT>0||p.stun>0||p.en<8)return;\n  if(G.pen&&G.pen.k===p.i)return;\n  const m=len(dx,dy);if(m<.001)return;\n  p.sv=SLIDE_V*(p.i==0?MY.tk:1);p.sdx=dx/m;p.sdy=dy/m;p.fx=p.sdx;p.fy=p.sdy;p.slideT=SLIDE_T;p.hitBall=0;p.fouled=0;p.en-=10;sfx('slide');\n  if(p.i==0)rumble(90,.25,.25);\n}\nfunction goal(r){\n  const b=G.ball;G.score[r]++;b.gone=1;G.phase='goal';G.pt=2;G.slow=.7;G.shake=14;G.pen=null;\n  const own=b.last>=0&&b.last!==r;\n  G.msg=(r==0?'BUT !':'But adverse')+(own?' (contre son camp)':'');G.msgT=2;\n  burst(b.x,b.y,r==0?ME:OP,70,320);sfx('goal');rumble(r==0?450:250,r==0?1:.5,.8);\n  for(const p of G.P){p.charging=0;p.charge=0}\n}\n// Football underground : pas de faute. Faucher le joueur le met au sol et libère la balle.\nfunction takedown(s,v){\n  s.fouled=1;s.slideT=0;s.vx*=.3;s.vy*=.3;s.stun=.6;s.pose='up';v.stun=1.0;v.pose='down';v.charging=0;v.charge=0;\n  const b=G.ball;\n  if(v.has){v.has=0;b.owner=-1;const a=Math.random()*6.283;b.vx=Math.cos(a)*170+s.sdx*120;b.vy=Math.sin(a)*170+s.sdy*120;b.vz=0;b.z=0;b.spin=0;b.nc=.45;b.ncw=v.i;b.last=s.i}\n  G.stats.fouls[s.i]++;G.shake=9;burst(v.x,v.y,'#8d949b',18,180);sfx('steal');\n  G.msg=s.i==0?'Au sol !':'Tu es au sol !';G.msgT=.9;rumble(v.i==0?320:200,v.i==0?1:.6,.6);\n}\nfunction cleanTackle(s){\n  const b=G.ball;s.hitBall=1;\n  if(b.owner===s.i)return;\n  if(b.owner>=0){const v=G.P[b.owner];v.has=0;v.charging=0;v.stun=.5;v.pose='stumble'}\n  b.owner=-1;b.vx=s.sdx*300+(Math.random()-.5)*130;b.vy=s.sdy*300+(Math.random()-.5)*130;b.vz=0;b.z=0;b.spin=0;b.nc=.3;b.ncw=s.i;b.last=s.i;\n  G.stats.tackles[s.i]++;G.shake=6;burst(b.x,b.y,GOLD,22,200);sfx('steal');\n  G.msg=s.i==0?'Tacle réussi !':'Taclé !';G.msgT=.8;rumble(s.i==0?160:240,s.i==0?.6:.9,.5);\n}\nfunction tackleCheck(s,o){\n  if(s.slideT<=0||s.fouled)return;\n  const b=G.ball,fx=s.x+s.sdx*(PR+9),fy=s.y+s.sdy*(PR+9);\n  if(!s.hitBall&&!b.gone&&b.z<12&&len(b.x-fx,b.y-fy)<BR+11)cleanTackle(s);\n  if(o.stun>0&&o.pose=='down')return;\n  const dF=len(o.x-fx,o.y-fy),d=len(o.x-s.x,o.y-s.y);\n  if(dF<PR+5||d<PR*2){\n    if(!s.hitBall)takedown(s,o);\n    else if(o.stun<=0){o.stun=.35;o.pose='stumble'}\n  }\n}\nfunction movePlayer(p,mx,my,sp,dt){\n  const d=AIP;\n  if(p.jinkCd>0)p.jinkCd-=dt;if(p.kickT>0)p.kickT-=dt;\n  if(p.stun>0){p.stun-=dt;mx=my=0;sp=false;if(p.stun<=0)p.pose=''}\n  let m=len(mx,my);if(m>1){mx/=m;my/=m;m=1}\n  if(p.slideT>0){\n    const k=p.slideT/SLIDE_T;p.vx=p.sdx*p.sv*(.3+.7*k);p.vy=p.sdy*p.sv*(.3+.7*k);p.slideT-=dt;\n    p.dust-=dt;if(p.dust<=0){p.dust=.03;G.fx.push({x:p.x-p.sdx*8,y:p.y-p.sdy*8,vx:(Math.random()-.5)*60,vy:(Math.random()-.5)*60,l:.4,c:'#8d949b'})}\n    if(p.slideT<=0&&!p.fouled){p.stun=p.hitBall?.3:.55;p.pose='up'}\n  }else if(p.jinkT>0){p.jinkT-=dt;p.vx=p.jx;p.vy=p.jy}\n  else{\n    const spr=sp&&p.en>2&&m>.2&&!p.charging;\n    let spd=190*(spr?1.45:1)*(p.charging?.5:1)*(p.en<15?.8:1)*(p.i==1?d.spd:MY.sp)*(p.has?.92:1);\n    if(G.pen&&G.pen.k!==p.i&&p.has)spd=0;\n    const k=Math.min(1,(p.stun>0?5:9)*dt);\n    p.vx+=(mx*spd-p.vx)*k;p.vy+=(my*spd-p.vy)*k;\n    if(spr)p.en=Math.max(0,p.en-26*dt);else p.en=Math.min(100,p.en+(p.charging?2:7)*dt);\n    if(m>.25&&p.stun<=0){p.fx=mx/m;p.fy=my/m}\n  }\n  if(p.charging)p.charge=Math.min(1,p.charge+dt/.85);\n  p.x+=p.vx*dt;p.y+=p.vy*dt;p.ph+=len(p.vx,p.vy)*dt*.075;\n  {const n=pushOut(p,PR);if(n){const vn=p.vx*n[0]+p.vy*n[1];if(vn<0){p.vx-=vn*n[0];p.vy-=vn*n[1];if(p.slideT>0){p.sdx-=n[0]*(p.sdx*n[0]+p.sdy*n[1]);p.sdy-=n[1]*(p.sdx*n[0]+p.sdy*n[1])}}}}\n  if(Math.abs(p.x)>HX-PR){p.x=Math.sign(p.x)*(HX-PR);p.vx=0}if(Math.abs(p.y)>HY-PR){p.y=Math.sign(p.y)*(HY-PR);p.vy=0}\n  if(G.pen&&G.pen.k===p.i){const dx=p.x-G.pen.mx,dy=p.y-G.pen.my,l=len(dx,dy);if(l>55){p.x=G.pen.mx+dx*55/l;p.y=G.pen.my+dy*55/l}}\n}\nfunction collidePlayers(){\n  const [a,c]=G.P;const dx=c.x-a.x,dy=c.y-a.y,d=len(dx,dy);\n  if(d<2*PR&&d>0){const nx=dx/d,ny=dy/d,o=(2*PR-d)/2;a.x-=nx*o;a.y-=ny*o;c.x+=nx*o;c.y+=ny*o}\n}\nfunction spawnObs(){\n  const n=1+(Math.random()*3|0),P=G.P,b=G.ball;let made=0;\n  for(let tr=0;tr<60&&made<n;tr++){\n    const r=Math.random();let o;\n    if(r<.4)o={type:'pil',r:20+Math.random()*14};\n    else if(r<.75){const hz=Math.random()<.5;o={type:'box',w:hz?55+Math.random()*45:10,h:hz?10:55+Math.random()*45}}\n    else{const a=24+Math.random()*16;o={type:'box',w:a,h:a}}\n    o.x=(Math.random()*2-1)*(HX-120);o.y=(Math.random()*2-1)*(HY-70);\n    const ext=o.type=='pil'?o.r:Math.max(o.w,o.h);\n    if(P.some(p=>len(p.x-o.x,p.y-o.y)<ext+PR+45)||len(b.x-o.x,b.y-o.y)<ext+40)continue;\n    if(G.obs.some(q=>len(q.x-o.x,q.y-o.y)<ext+(q.type=='pil'?q.r:Math.max(q.w,q.h))+45))continue;\n    o.st='warn';o.t=0;o.k=0;o.life=8+Math.random()*5;G.obs.push(o);made++;\n  }\n  if(made){G.msg='Obstacles !';G.msgT=1.1}\n}\nfunction obsTick(dt){\n  if(G.obsOn&&G.phase=='play'){G.obsT-=dt;if(G.obsT<=0){spawnObs();G.obsT=13+Math.random()*8}}\n  for(const o of G.obs){o.t+=dt;\n    if(o.st=='warn'){if(o.t>1.3){o.st='up';o.t=0;sfx('rise');G.shake=Math.max(G.shake,5);rumble(220,.45,.25)}}\n    else if(o.st=='up'){o.k=Math.min(1,o.k+dt*3.5);if(o.t>o.life){o.st='down';o.t=0}}\n    else{o.k-=dt*1.6;if(o.k<=0)o.dead=1}}\n  for(let i=G.obs.length-1;i>=0;i--)if(G.obs[i].dead)G.obs.splice(i,1);\n}\nfunction step(dt){\n  const P=G.P,b=G.ball;G.t+=dt;\n  if(G.phase=='ready'){G.pt-=dt;if(G.pt<=0)G.phase='play'}\n  obsTick(dt);\n  const play=G.phase=='play';\n  const ai=play?aiThink(dt):{mx:0,my:0,sprint:false};\n  movePlayer(P[0],play?IN.mx:0,play?IN.my:0,play&&IN.sprint,dt);\n  movePlayer(P[1],ai.mx,ai.my,ai.sprint,dt);\n  if(play){tackleCheck(P[0],P[1]);if(G.phase=='play')tackleCheck(P[1],P[0])}\n  collidePlayers();\n  if(b.owner>=0)attach(P[b.owner]);\n  else if(b.gone){b.x+=b.vx*dt;b.y+=b.vy*dt;b.vx*=.97;b.vy*=.97}\n  else{\n    if(b.nc>0)b.nc-=dt;\n    const r=ballMove(b,dt,G.t);b.rot+=len(b.vx,b.vy)*dt/BR;\n    if(b.bar&&G.phase=='play'){G.msg='Trop haut !';G.msgT=.8;sfx('bar');G.shake=5}\n    else if(b.bounced>160&&G.t-b.bt>.08){sfx('wall');b.bt=G.t;if(b.bounced>500)G.shake=Math.max(G.shake,3)}\n    if(r>=0){if(G.phase=='play')goal(r);else b.gone=1}\n    else if(b.z<14)for(const p of P){\n      if(p.stun>0&&p.pose=='down')continue;\n      const dx=b.x-p.x,dy=b.y-p.y,d=len(dx,dy)||1;\n      if(d<PR+BR){\n        const bs=len(b.vx,b.vy);\n        if(!(b.nc>0&&b.ncw==p.i)&&bs<CATCH&&p.slideT<=0&&p.stun<=0&&G.phase=='play'&&b.z<6){\n          b.owner=p.i;p.has=1;b.last=p.i;b.spin=0;p.charge=0;p.charging=0;sfx('catch');\n          if(p.i==0)rumble(50,0,.35);else AI.onCatch();\n          break;\n        }\n        const rvx=b.vx-p.vx,rvy=b.vy-p.vy,nx=dx/d,ny=dy/d,vn=rvx*nx+rvy*ny;\n        if(vn<0){b.vx-=1.6*vn*nx;b.vy-=1.6*vn*ny;b.spin*=.3;\n          if(bs>300&&b.last!==p.i){G.stats.saves[p.i]++;G.shake=Math.max(G.shake,5);sfx('block');burst(b.x,b.y,'#ffffff',12,160);if(p.i==0){rumble(120,.5,.4);G.msg='Arrêt !';G.msgT=.6}}\n          b.last=p.i;\n        }\n        b.x=p.x+nx*(PR+BR);b.y=p.y+ny*(PR+BR);\n      }\n    }\n  }\n  b.trail.push(b.x,b.y-b.z*.6);if(b.trail.length>24)b.trail.splice(0,2);\n  if(play){G.rt-=dt;if(G.rt<=0){G.phase='timeout';G.pt=1.2;G.msg=G.pen?'Penalty manqué':'Temps écoulé';G.msgT=1.2;G.pen=null;dropBall()}}\n  if(G.phase=='stop'){G.pt-=dt;if(G.pt<=0){G.att=G.next.att;const pen=G.next.pen;G.next=null;startRound(pen)}}\n  if(G.phase=='timeout'||G.phase=='goal'){G.pt-=dt;if(G.pt<=0){if(Math.max(G.score[0],G.score[1])>=WIN){endMatch();return}G.att^=1;startRound(false)}}\n  for(const f of G.fx){f.x+=f.vx*dt;f.y+=f.vy*dt;f.vx*=.96;f.vy*=.96;f.l-=dt}\n  G.fx=G.fx.filter(f=>f.l>0);\n  if(G.shake>0)G.shake=Math.max(0,G.shake-30*dt);\n  if(G.msgT>0)G.msgT-=dt;\n}\nfunction dropBall(){const b=G.ball;if(b.owner>=0){const p=G.P[b.owner];p.has=0;p.charging=0;b.owner=-1;b.vx=p.vx*.5;b.vy=p.vy*.5}}\nfunction burst(x,y,c,n,sp){for(let i=0;i<n;i++){const a=Math.random()*6.283,v=sp*(.3+Math.random());G.fx.push({x,y,vx:Math.cos(a)*v,vy:Math.sin(a)*v,l:.5+Math.random()*.6,c})}}\n\n// ---------- IA ----------\nconst AI={\n  reset(att){const d=AIP;this.hold=att?d.think+.2:0;this.plan=null;this.replan=0;this.pend=[];this.blind=0;this.tackCd=.8;this.fcd=1;this.tgt=.6;this.ax=-1;this.ay=0;this.lmx=0;this.lmy=0;this.type='shot'},\n  onShot(){this.blind=AIP.react},\n  onFeint(){this.pend.push(G.t+AIP.react*.5)},\n  onCatch(){this.hold=AIP.think*.6;this.plan=null}\n};\nfunction findShot(p,o){\n  let best=null,bs=-1e9;const N=96,ef=.7+.3*Math.min(1,p.en/30);\n  const tryShot=(dx,dy,pw,type,bonus)=>{\n    const sx=p.x+dx*(PR+BR+1),sy=p.y+dy*(PR+BR+1);if(Math.abs(sx)>HX-BR-2||Math.abs(sy)>HY-BR-2)return;\n    let r;\n    if(type=='lob'){const hs=(230+230*pw)*ef;r=simPath(sx,sy,dx*hs,dy*hs,0,1,230+170*pw,G.t+pw*.85,2,o)}\n    else{const sp=(330+600*pw)*ef;r=simPath(sx,sy,dx*sp,dy*sp,0,pw>.8?1:0,pw>.8?60:0,G.t+pw*.85,1.4,o)}\n    if(r.goal!==1||r.clear<PR+BR+6)return;\n    const s=Math.min(r.clear,90)-r.t*70-pw*10+bonus;\n    if(s>bs){bs=s;best={dx,dy,pw,type}}\n  };\n  for(let k=0;k<N;k++){const a=k/N*Math.PI*2;for(const pw of [.5,.85])tryShot(Math.cos(a),Math.sin(a),pw,'shot',0)}\n  if(len(o.x-p.x,o.y-p.y)<120){const h=holePos(1,G.t),ha=Math.atan2(h[1]-p.y,h[0]-p.x);for(const da of [-.08,0,.08])for(const pw of [.3,.55,.8,1])tryShot(Math.cos(ha+da),Math.sin(ha+da),pw,'lob',-25)}\n  return best;\n}\nfunction aiThink(dt){\n  const A=AI,p=G.P[1],o=G.P[0],b=G.ball,d=AIP,O={mx:0,my:0,sprint:false};\n  A.tackCd-=dt;A.fcd-=dt;A.replan-=dt;if(A.blind>0)A.blind-=dt;\n  if(p.stun>0||p.slideT>0||p.jinkT>0)return O;\n  const to=(x,y,spr)=>{const dx=x-p.x,dy=y-p.y,l=len(dx,dy);if(l>3){const k=Math.min(1,l/40);O.mx=dx/l*k;O.my=dy/l*k}O.sprint=spr&&p.en>30&&l>80;\n    for(const ob of OBS){if(ob.k<.3)continue;const q=obsNear(ob,p.x,p.y),ax=p.x-q[0],ay=p.y-q[1],dd=len(ax,ay)||1;\n      if(dd<PR+30&&(dx*-ax+dy*-ay)>0){const nx=ax/dd,ny=ay/dd,tx=-ny,ty=nx,sg=(tx*dx+ty*dy)>=0?1:-1;O.mx+=nx*.5+tx*sg*.9;O.my+=ny*.5+ty*sg*.9}}};\n  // Mord au crochet : tacle là où était la balle\n  if(A.pend.length&&G.t>=A.pend[0]){\n    A.pend.shift();\n    if(o.has&&len(o.x-p.x,o.y-p.y)<130&&Math.random()<d.bite&&!(G.pen&&G.pen.k===1)){tackle(p,o.x+o.fx*20-o.vx*.15-p.x,o.y+o.fy*20-o.vy*.15-p.y);A.tackCd=1.2;return O}\n  }\n  if(p.has){\n    if(A.hold>0)A.hold-=dt;\n    if(p.charging){\n      O.mx=A.ax*.3;O.my=A.ay*.3;\n      if(p.charge>=A.tgt){const n=(Math.random()-.5)*2*d.aim,c=Math.cos(n),s=Math.sin(n);p.fx=A.ax*c-A.ay*s;p.fy=A.ax*s+A.ay*c;release(p,0);A.plan=null;A.hold=d.think*.5}\n      return O;\n    }\n    if(A.replan<=0){A.replan=.12;A.plan=findShot(p,o)}\n    if(A.plan&&A.hold<=0){A.ax=A.plan.dx;A.ay=A.plan.dy;p.fx=A.ax;p.fy=A.ay;A.tgt=A.plan.pw;startCharge(p,A.plan.type);O.mx=A.ax*.3;O.my=A.ay*.3;return O}\n    if(len(o.x-p.x,o.y-p.y)<85&&A.fcd<=0&&Math.random()<d.feint*dt*4){jink(p,0,0);A.fcd=1.4;return O}\n    const hy=holeY(1,G.t);let best=null,bsc=-1;\n    for(const [x,y] of [[-HX+160,clamp(hy-130,-HY+40,HY-40)],[-HX+190,hy],[-HX+160,clamp(hy+130,-HY+40,HY-40)]]){const s=len(x-o.x,y-o.y);if(s>bsc){bsc=s;best=[x,y]}}\n    to(best[0],best[1],true);return O;\n  }\n  if(o.has){\n    const g=holePos(0,G.t);\n    if(G.pen&&G.pen.k===1){const gx=o.x-g[0],gy=o.y-g[1],gl=len(gx,gy)||1;to(g[0]+gx/gl*34,g[1]+gy/gl*34,false);return O}\n    const gx=g[0]-o.x,gy=g[1]-o.y,gl=len(gx,gy)||1,k=Math.min(80,gl*.5);\n    to(o.x+gx/gl*k,o.y+gy/gl*k,true);\n    const bd=len(b.x-p.x,b.y-p.y);\n    if(bd<80&&A.tackCd<=0&&Math.random()<d.tack*dt*(o.charging?2.2:1)){\n      const front=(p.x-o.x)*o.fx+(p.y-o.y)*o.fy>0;\n      if(front||Math.random()<.7){tackle(p,b.x+o.vx*.15-p.x,b.y+o.vy*.15-p.y);A.tackCd=1.1}\n      else A.tackCd=.3;\n    }\n    return O;\n  }\n  if(A.blind>0){O.mx=A.lmx;O.my=A.lmy;return O}\n  const pts=[];simPath(b.x,b.y,b.vx,b.vy,b.spin,b.z,b.vz,G.t,1.2,null,pts);\n  const spd=190*1.45*d.spd;let tx=b.x,ty=b.y;\n  for(let j=0;j<pts.length;j+=3){const t=(j/3+1)/60;tx=pts[j];ty=pts[j+1];if(pts[j+2]<14&&len(tx-p.x,ty-p.y)-PR<=spd*t)break}\n  to(tx,ty,true);\n  const bs=len(b.vx,b.vy),dd=len(b.x-p.x,b.y-p.y);\n  if(bs>300&&dd<95&&A.tackCd<=0&&b.z<12){const r=simPath(b.x,b.y,b.vx,b.vy,b.spin,b.z,b.vz,G.t,.8,null);if(r.goal===0){tackle(p,tx-p.x,ty-p.y);A.tackCd=1}}\n  else if(bs<CATCH&&dd<75&&len(b.x-o.x,b.y-o.y)<dd+20&&A.tackCd<=0&&b.z<8){tackle(p,b.x-p.x,b.y-p.y);A.tackCd=1}\n  A.lmx=O.mx;A.lmy=O.my;return O;\n}\n\n// ---------- Actions du joueur (une fois par image) ----------\nfunction humanActions(){\n  if(G.phase!='play')return;\n  const p=G.P[0],b=G.ball;\n  if(IN.shootDown){\n    if(p.has)startCharge(p,'shot');\n    else{let dx=IN.mx,dy=IN.my;if(len(dx,dy)<.3){dx=b.x-p.x;dy=b.y-p.y}tackle(p,dx,dy)}\n  }\n  if(IN.lobDown&&p.has)startCharge(p,'lob');\n  if(p.charging&&((p.ctype=='shot'&&IN.shootUp)||(p.ctype=='lob'&&IN.lobUp)))release(p,IN.curve);\n  if(IN.feintDown)jink(p,IN.mx,IN.my);\n}\n\n// ---------- Dessin ----------\nlet demo={x:0,y:0,z:0,vz:0,vx:420,vy:250,spin:0,t:0,rot:0,trail:[]};\nconst CAM={x:0,y:0};\nfunction view(){\n  const top=78,bot=(T.on&&state=='play'&&W<HH*1.15)?210:18;\n  const av=Math.min(W-24,HH-top-bot);let s=Math.max(.3,Math.min((W-24)/(2*HX+90),(HH-top-bot)/(2*HY+90)));\n  const ox=W/2,oy=top+(HH-top-bot)/2;\n  if(state=='menu'||!G)return{s,x:ox,y:oy,cx:0,cy:0};\n  s*=1.18;\n  // caméra qui suit le jeu (balle et joueur), bornée à l'arène\n  const b=G.ball,p=G.P[0],tx=b.x*.7+p.x*.3,ty=b.y*.7+p.y*.3,hw=(W/2)/s,hh=((HH-top-bot)/2)/s,mx=Math.max(0,HX+60-hw),my=Math.max(0,HY+60-hh);\n  const k=Math.min(1,.12*60*(1/60));CAM.x+=(clamp(tx,-mx,mx)-CAM.x)*k;CAM.y+=(clamp(ty,-my,my)-CAM.y)*k;\n  return{s,x:ox-CAM.x*s,y:oy-CAM.y*s,cx:CAM.x,cy:CAM.y};\n}\n// flèche au bord de l'écran vers un but hors champ\nfunction goalArrow(i,v,col){\n  const h=holePos(i,G.t),sx=v.x+h[0]*v.s,sy=v.y+h[1]*v.s,m=34,top=84;\n  if(sx>m&&sx<W-m&&sy>top&&sy<HH-m)return;\n  const ax=clamp(sx,m,W-m),ay=clamp(sy,top,HH-m),a=Math.atan2(sy-ay,sx-ax);\n  const c=cx;c.save();c.translate(ax,ay);c.rotate(a);c.fillStyle=col;c.globalAlpha=.9;c.beginPath();c.moveTo(14,0);c.lineTo(-8,-10);c.lineTo(-3,0);c.lineTo(-8,10);c.closePath();c.fill();c.restore();\n}\n// Sol de béton peint (graffitis) pré-rendu une fois\nlet FLOOR=null;\nfunction mkFloor(){\n  const sc=2,cv2=document.createElement('canvas');cv2.width=(2*HX)*sc;cv2.height=(2*HY)*sc;const g=cv2.getContext('2d');g.scale(sc,sc);\n  let sd=7;const rnd=()=>(sd=(sd*16807)%2147483647)/2147483647;\n  g.fillStyle='#d9dde0';g.fillRect(0,0,2*HX,2*HY);\n  for(let i=0;i<900;i++){g.fillStyle=`rgba(${rnd()<.5?'90,100,110':'255,255,255'},${rnd()*.08})`;g.fillRect(rnd()*2*HX,rnd()*2*HY,rnd()*30+4,rnd()*30+4)}\n  // dalles\n  g.strokeStyle='rgba(80,90,100,.18)';g.lineWidth=1.2;for(let x=0;x<=2*HX;x+=66){g.beginPath();g.moveTo(x,0);g.lineTo(x,2*HY);g.stroke()}for(let y=0;y<=2*HY;y+=67){g.beginPath();g.moveTo(0,y);g.lineTo(2*HX,y);g.stroke()}\n  // graffitis : traits d'encre, éclaboussures, coulures\n  for(let i=0;i<24;i++){\n    const x=rnd()*2*HX,y=rnd()*2*HY,dark=rnd()<.75;g.strokeStyle=dark?`rgba(25,28,34,${.12+rnd()*.25})`:`rgba(120,130,140,${.15+rnd()*.2})`;\n    g.lineWidth=1+rnd()*(rnd()<.2?9:4);g.lineCap='round';g.beginPath();g.moveTo(x,y);let px=x,py=y;\n    const n=2+(rnd()*4|0);for(let k=0;k<n;k++){const nx=px+(rnd()-.5)*90,ny=py+(rnd()-.5)*90;g.quadraticCurveTo(px+(rnd()-.5)*60,py+(rnd()-.5)*60,nx,ny);px=nx;py=ny}g.stroke();\n  }\n  for(let i=0;i<14;i++){const x=rnd()*2*HX,y=rnd()*2*HY;g.fillStyle=`rgba(25,28,34,${.12+rnd()*.25})`;for(let k=0;k<14;k++){g.beginPath();g.arc(x+(rnd()-.5)*40,y+(rnd()-.5)*40,rnd()*3.5,0,7);g.fill()}}\n  // grilles métalliques\n  for(const [x,y] of [[HX-150,40],[HX+70,2*HY-90]]){g.fillStyle='rgba(60,70,80,.55)';g.fillRect(x,y,80,50);g.strokeStyle='rgba(20,25,30,.8)';g.lineWidth=1;for(let k=4;k<80;k+=5){g.beginPath();g.moveTo(x+k,y+3);g.lineTo(x+k,y+47);g.stroke()}}\n  FLOOR=cv2;\n}\nfunction drawArena(t){\n  const c=cx;if(!FLOOR)mkFloor();\n  c.drawImage(FLOOR,-HX,-HY,2*HX,2*HY);\n  // lumière circulaire du plafond\n  let lg=c.createRadialGradient(0,0,20,0,0,HY*1.1);lg.addColorStop(0,'rgba(220,255,255,.38)');lg.addColorStop(.55,'rgba(150,235,240,.12)');lg.addColorStop(1,'rgba(20,40,60,.0)');c.fillStyle=lg;c.fillRect(-HX,-HY,2*HX,2*HY);\n  c.strokeStyle='rgba(120,240,245,.22)';c.lineWidth=14;c.beginPath();c.arc(0,0,150,0,7);c.stroke();\n  const vg=c.createRadialGradient(0,0,HY*.6,0,0,HX*1.25);vg.addColorStop(0,'rgba(10,20,30,0)');vg.addColorStop(1,'rgba(10,20,30,.45)');c.fillStyle=vg;c.fillRect(-HX,-HY,2*HX,2*HY);\n  // halo devant les trous\n  for(let i=0;i<2;i++){const h=holePos(i,t),col=i==0?ME:OP,hg=c.createRadialGradient(h[0],h[1],4,h[0],h[1],90);hg.addColorStop(0,col+'55');hg.addColorStop(1,col+'00');\n    c.save();c.beginPath();c.rect(-HX,-HY,2*HX,2*HY);c.clip();c.fillStyle=hg;c.fillRect(h[0]-95,h[1]-95,190,190);c.restore()}\n  // gravité\n  const gv=grav(t);\n  if(gv){const a=Math.atan2(gv[1],gv[0]);c.save();c.rotate(a);c.globalAlpha=.55;c.strokeStyle='#4b3c8a';c.fillStyle='#4b3c8a';c.lineWidth=6;c.lineCap='round';\n    c.beginPath();c.moveTo(-28,0);c.lineTo(22,0);c.stroke();c.beginPath();c.moveTo(34,0);c.lineTo(16,-12);c.lineTo(16,12);c.closePath();c.fill();c.restore()}\n  // murs vus d'en haut : bandeau de béton avec biseau intérieur et néon\n  const WT=26;\n  c.fillStyle='#b9c0c5';c.fillRect(-HX-WT,-HY-WT,2*HX+2*WT,WT);c.fillRect(-HX-WT,HY,2*HX+2*WT,WT);c.fillRect(-HX-WT,-HY,WT,2*HY);c.fillRect(HX,-HY,WT,2*HY);\n  c.fillStyle='rgba(0,0,0,.18)';c.fillRect(-HX,-HY,2*HX,7);c.fillRect(-HX,-HY,7,2*HY);\n  c.fillStyle='rgba(255,255,255,.5)';c.fillRect(-HX,HY-3,2*HX,3);c.fillRect(HX-3,-HY,3,2*HY);\n  c.strokeStyle='#62f0f2';c.shadowColor='#62f0f2';c.shadowBlur=14;c.lineWidth=3;c.strokeRect(-HX-WT+5,-HY-WT+5,2*HX+2*WT-10,2*HY+2*WT-10);c.shadowBlur=0;\n  c.strokeStyle='rgba(30,35,40,.6)';c.lineWidth=1.5;c.strokeRect(-HX,-HY,2*HX,2*HY);\n  // trous dans les murs\n  for(let i=0;i<2;i++){const h=holePos(i,t),sg=i==0?1:-1,col=i==0?ME:OP,x=h[0],y=h[1];\n    const hg=c.createRadialGradient(x+sg*6,y,2,x,y,HOLER);hg.addColorStop(0,'#000');hg.addColorStop(.7,'#07080d');hg.addColorStop(1,'#2a2f38');\n    c.fillStyle=hg;c.beginPath();c.ellipse(x+sg*(WT*.35),y,WT*.75,HOLER,0,0,7);c.fill();\n    c.strokeStyle=col;c.lineWidth=2.5;c.shadowColor=col;c.shadowBlur=12;c.beginPath();c.ellipse(x+sg*(WT*.35),y,WT*.75,HOLER,0,0,7);c.stroke();c.shadowBlur=0;\n  }\n}\n// pluie fine\nconst RAIN=[...Array(90)].map(()=>[Math.random(),Math.random(),.6+Math.random()*.8]);\nfunction drawRain(now){const c=cx;c.strokeStyle='rgba(200,235,255,.13)';c.lineWidth=1;c.beginPath();\n  for(const [x,y,s] of RAIN){const yy=((y+now*.9*s)%1)*HH,xx=((x+now*.15*s)%1)*W;c.moveTo(xx,yy);c.lineTo(xx-4*s,yy-16*s)}c.stroke()}\nfunction drawWarn(o,t){const c=cx,a=.35+.35*Math.sin(t*14);c.save();c.globalAlpha=a;c.strokeStyle='#ff6a2b';c.fillStyle='rgba(255,106,43,.18)';c.lineWidth=3;c.setLineDash([8,6]);\n  c.beginPath();if(o.type=='pil')c.arc(o.x,o.y,o.r,0,7);else c.rect(o.x-o.w,o.y-o.h,2*o.w,2*o.h);c.fill();c.stroke();c.restore()}\nfunction drawObs(o){\n  const c=cx,H=OH*o.k*.6;if(o.k<=0)return;\n  c.fillStyle='rgba(10,15,25,.28)';\n  if(o.type=='pil'){\n    c.beginPath();c.ellipse(o.x+7,o.y+6,o.r+2,o.r*.85,0,0,7);c.fill();\n    const g=c.createLinearGradient(o.x-o.r,0,o.x+o.r,0);g.addColorStop(0,'#7d868d');g.addColorStop(.45,'#b4bcc2');g.addColorStop(1,'#646c73');\n    c.fillStyle=g;c.fillRect(o.x-o.r,o.y-H,2*o.r,H);c.beginPath();c.arc(o.x,o.y,o.r,0,Math.PI);c.fill();\n    c.fillStyle='#d3d9dd';c.beginPath();c.arc(o.x,o.y-H,o.r,0,7);c.fill();c.strokeStyle='#62f0f2';c.lineWidth=2;c.beginPath();c.arc(o.x,o.y-H,o.r-3,0,7);c.stroke();\n  }else{\n    c.fillRect(o.x-o.w+7,o.y-o.h+6,2*o.w,2*o.h);\n    c.fillStyle='#868f96';c.fillRect(o.x-o.w,o.y+o.h-H,2*o.w,H);\n    c.fillStyle='#d3d9dd';c.fillRect(o.x-o.w,o.y-o.h-H,2*o.w,2*o.h);\n    c.strokeStyle='#62f0f2';c.lineWidth=2;c.strokeRect(o.x-o.w+3,o.y-o.h-H+3,2*o.w-6,2*o.h-6);\n    c.strokeStyle='rgba(30,35,40,.5)';c.lineWidth=1;c.strokeRect(o.x-o.w,o.y-o.h-H,2*o.w,2*o.h+H);\n  }\n}\nfunction drawBall(b,alpha){\n  const c=cx,z=b.z||0,sc=1+z/110,y=b.y-z*.6;\n  for(let j=0;j<b.trail.length;j+=2){const k=j/b.trail.length;c.fillStyle=`rgba(255,160,60,${k*.25*alpha})`;c.beginPath();c.arc(b.trail[j],b.trail[j+1],BR*k,0,7);c.fill()}\n  c.globalAlpha=alpha*Math.max(.25,1-z/120);c.fillStyle='rgba(0,0,0,.45)';c.beginPath();c.ellipse(b.x+2+z*.15,b.y+4+z*.1,BR*(1-z/250),BR*.7*(1-z/250),0,0,7);c.fill();\n  c.globalAlpha=alpha;\n  c.shadowColor='#ffb347';c.shadowBlur=10;c.fillStyle='#ff8a1f';c.beginPath();c.arc(b.x,y,BR*sc,0,7);c.fill();c.shadowBlur=0;\n  c.save();c.beginPath();c.arc(b.x,y,BR*sc,0,7);c.clip();c.fillStyle='#22c7c0';\n  const r=b.rot||0;c.beginPath();c.arc(b.x+Math.cos(r)*2*sc,y+Math.sin(r*.7)*2*sc,2.6*sc,0,7);c.fill();\n  for(let k=0;k<3;k++){const a=r+k*2.094;c.beginPath();c.ellipse(b.x+Math.cos(a)*5.5*sc,y+Math.sin(a)*5.5*sc,3.4*sc,1.6*sc,a+1.2,0,7);c.fill()}\n  c.restore();c.globalAlpha=1;\n}\nfunction limb(x1,y1,x2,y2,w,col){const c=cx;c.strokeStyle=col;c.lineWidth=w;c.lineCap='round';c.beginPath();c.moveTo(x1,y1);c.lineTo(x2,y2);c.stroke()}\nfunction drawFooty(p,kit,lbl,col,t){\n  const c=cx,a=Math.atan2(p.fy,p.fx);\n  // anneau de sélection au sol\n  c.strokeStyle=col;c.globalAlpha=.85;c.lineWidth=2.5;c.beginPath();c.ellipse(p.x,p.y+3,PR+5,PR+3,0,0,7);c.stroke();c.globalAlpha=1;\n  c.fillStyle='rgba(0,0,0,.35)';c.beginPath();c.ellipse(p.x+3,p.y+5,PR,PR*.8,0,0,7);c.fill();\n  c.save();c.translate(p.x,p.y);c.rotate(a);c.scale(1.15,1.15);\n  const down=p.stun>0&&p.pose=='down',slide=p.slideT>0;\n  if(down){\n    c.rotate(Math.PI/2);\n    limb(-4,-4,-22,-7,5,kit.socks);limb(-4,4,-22,8,5,kit.socks);\n    c.fillStyle=kit.boots;c.beginPath();c.arc(-23,-7,3,0,7);c.arc(-23,8,3,0,7);c.fill();\n    c.fillStyle=kit.shorts;c.beginPath();c.ellipse(-4,0,6,8,0,0,7);c.fill();\n    c.fillStyle=kit.shirt;c.beginPath();c.ellipse(6,0,10,11,0,0,7);c.fill();\n    limb(6,-10,12,-18,4.5,kit.sleeve);limb(6,10,14,16,4.5,kit.sleeve);\n    c.fillStyle=kit.skin;c.beginPath();c.arc(19,0,6,0,7);c.fill();c.fillStyle=kit.hair;c.beginPath();c.arc(21,0,6,-1.6,1.6);c.fill();\n  }else if(slide){\n    limb(0,4,26,5,5.5,kit.socks);limb(0,-4,10,-12,5.5,kit.socks);\n    c.fillStyle=kit.boots;c.beginPath();c.ellipse(28,5,4,3,0,0,7);c.fill();c.beginPath();c.arc(11,-13,3,0,7);c.fill();\n    c.fillStyle=kit.shorts;c.beginPath();c.ellipse(-2,0,7,8,0,0,7);c.fill();\n    c.fillStyle=kit.shirt;c.beginPath();c.ellipse(-10,0,8,12,0,0,7);c.fill();\n    limb(-10,-11,-6,-22,4.5,kit.sleeve);limb(-10,11,-18,18,4.5,kit.sleeve);\n    c.fillStyle=kit.skin;c.beginPath();c.arc(-16,0,6,0,7);c.fill();c.fillStyle=kit.hair;c.beginPath();c.arc(-18,0,6,1.6,4.7);c.fill();\n  }else{\n    const sp=len(p.vx,p.vy),amp=Math.min(1,sp/120),s=Math.sin(p.ph)*amp,kick=p.kickT>0?p.kickT/.18:0;\n    const lf=kick?14*kick:s*10,rf=-s*10;\n    limb(0,-5,lf,-6,6.5,kit.socks);limb(0,5,rf,6,6.5,kit.socks);\n    c.fillStyle=kit.boots;c.beginPath();c.ellipse(lf+2,-6,3.6,2.8,0,0,7);c.fill();c.beginPath();c.ellipse(rf+2,6,3.6,2.8,0,0,7);c.fill();\n    c.fillStyle=kit.shorts;c.beginPath();c.ellipse(-1,0,6,9,0,0,7);c.fill();\n    const arm=p.stun>0&&p.pose=='stumble'?7:0;\n    limb(-1,-12,-s*8,-17-arm,4.5,kit.sleeve);limb(-1,12,s*8,17+arm,4.5,kit.sleeve);\n    c.fillStyle=kit.skin;c.beginPath();c.arc(-s*8,-17-arm,2.6,0,7);c.arc(s*8,17+arm,2.6,0,7);c.fill();\n    c.fillStyle=kit.shirt;c.beginPath();c.ellipse(-1,0,8,13.5,0,0,7);c.fill();c.strokeStyle='rgba(0,0,0,.35)';c.lineWidth=1;c.stroke();\n    c.fillStyle=kit.shirt2;c.fillRect(-9,-1.5,16,3);\n    c.fillStyle=kit.skin;c.beginPath();c.arc(1,0,6.4,0,7);c.fill();\n    c.fillStyle=kit.hair;c.beginPath();c.arc(0,0,6.4,1.75,4.53);c.fill();\n  }\n  c.restore();\n  if(p.charging){c.strokeStyle=p.ctype=='lob'?'#9dffb0':GOLD;c.lineWidth=4;c.lineCap='round';c.beginPath();c.arc(p.x,p.y,PR+11,-Math.PI/2,-Math.PI/2+p.charge*Math.PI*2);c.stroke();c.lineCap='butt'}\n  if(p.stun>0&&p.pose!='up'){c.fillStyle=GOLD;for(let k=0;k<3;k++){const b=t*7+k*2.09;c.beginPath();c.arc(p.x+Math.cos(b)*13,p.y-PR-10+Math.sin(b)*4,2.4,0,7);c.fill()}}\n  c.font='800 10px Inter,system-ui,sans-serif';c.textAlign='center';c.lineWidth=3;c.strokeStyle='rgba(255,255,255,.85)';c.strokeText(lbl,p.x,p.y+PR+18);c.fillStyle='#14182a';c.fillText(lbl,p.x,p.y+PR+18);\n}\nfunction drawPreview(p){\n  const c=Math.max(.12,p.charge),ef=.7+.3*Math.min(1,p.en/30),sx=p.x+p.fx*(PR+BR+1),sy=p.y+p.fy*(PR+BR+1),pts=[];\n  let r;\n  if(p.ctype=='lob'){const hs=(230+230*c)*ef;r=simPath(sx,sy,p.fx*hs+p.vx*.2,p.fy*hs+p.vy*.2,IN.curve*1.2,1,230+170*c,G.t,1.6,null,pts)}\n  else{const sp=(330+600*c)*ef;r=simPath(sx,sy,p.fx*sp+p.vx*.25,p.fy*sp+p.vy*.25,IN.curve*2.6,c>.8?1:0,c>.8?60:0,G.t,.75,null,pts)}\n  cx.fillStyle=r.goal===0?GOLD:(p.ctype=='lob'?'#9dffb0':ME);\n  for(let j=0;j<pts.length;j+=9){const k=1-j/pts.length;cx.globalAlpha=k*.85;cx.beginPath();cx.arc(pts[j],pts[j+1]-pts[j+2]*.6,2.3,0,7);cx.fill()}\n  cx.globalAlpha=1;\n}\nfunction bar(x,y,w,h,v,col,right){const c=cx;c.fillStyle='rgba(255,255,255,.1)';c.beginPath();c.roundRect(x,y,w,h,h/2);c.fill();c.fillStyle=v<.15?'#ff5d6c':col;const ww=Math.max(h,w*v);c.beginPath();c.roundRect(right?x+w-ww:x,y,ww,h,h/2);c.fill()}\nfunction card(x,y){cx.fillStyle=GOLD;cx.beginPath();cx.roundRect(x,y,9,13,2);cx.fill()}\nfunction render(ft){\n  const c=cx;c.setTransform(DPR,0,0,DPR,0,0);\n  c.fillStyle='#080919';c.fillRect(0,0,W,HH);\n  const now=performance.now()/1000;\n  for(const [x,y,r,p] of STARS){c.globalAlpha=.25+.25*Math.sin(now*1.2+p);c.fillStyle='#fff';c.beginPath();c.arc(x*W,y*HH,r,0,7);c.fill()}\n  c.globalAlpha=1;\n  const v=view(),sh=G&&state!='menu'?G.shake:0;\n  c.save();c.translate(v.x+(Math.random()-.5)*sh,v.y+(Math.random()-.5)*sh);c.scale(v.s,v.s);\n  if(state=='menu'){\n    MODE=0;OBS=[];demo.t+=ft;drawArena(demo.t);\n    for(let k=0;k<2;k++){const r=ballMove(demo,ft/2,demo.t);demo.rot+=len(demo.vx,demo.vy)*ft/2/BR;if(r>=0){demo.x=0;demo.y=0;demo.z=0;demo.vz=0;const a=Math.random()*6.283;demo.vx=Math.cos(a)*520;demo.vy=Math.sin(a)*520}}\n    if(len(demo.vx,demo.vy)<200){const a=Math.random()*6.283;demo.vx+=Math.cos(a)*450;demo.vy+=Math.sin(a)*450;demo.spin=(Math.random()-.5)*3}\n    demo.trail.push(demo.x,demo.y);if(demo.trail.length>24)demo.trail.splice(0,2);drawBall(demo,1);\n    c.restore();drawRain(now);return;\n  }\n  MODE=0;OBS=G.obs;\n  drawArena(G.t);\n  const p0=G.P[0],p1=G.P[1],b=G.ball;\n  if(p0.charging&&G.phase=='play')drawPreview(p0);\n  // ordre d'affichage : de haut en bas\n  for(const o of G.obs)if(o.st=='warn')drawWarn(o,G.t);\n  const ents=[...G.obs.filter(o=>o.st!='warn').map(o=>[o.y+(o.type=='pil'?o.r:o.h),()=>drawObs(o)]),[p1.y,()=>drawFooty(p1,KIT[1],SET.op.n.split(' ')[0],OP,G.t)],[p0.y,()=>drawFooty(p0,KIT[0],'TOI · '+SET.me.n,ME,G.t)],[b.y+(b.z>5?40:0),()=>drawBall(b,b.gone?Math.max(0,1-(Math.abs(b.x)-HX)/60):1)]];\n  ents.sort((x,y)=>x[0]-y[0]).forEach(e=>e[1]());\n  for(const f of G.fx){c.globalAlpha=Math.min(1,f.l*2);c.fillStyle=f.c;c.beginPath();c.arc(f.x,f.y,2.5,0,7);c.fill()}\n  c.globalAlpha=1;\n  if(G.msgT>0){c.globalAlpha=Math.min(1,G.msgT*3);c.font=`400 ${G.phase=='goal'?60:36}px \"Bagel Fat One\",system-ui,sans-serif`;c.textAlign='center';c.lineWidth=8;c.strokeStyle='rgba(8,9,25,.85)';\n    const y=G.phase=='goal'?-10:-HY*.62;c.strokeText(G.msg,0,y);c.fillStyle=G.phase=='goal'?(G.msg.startsWith('BUT')?ME:OP):(G.phase=='stop'?GOLD:'#fff');c.fillText(G.msg,0,y);c.globalAlpha=1}\n  c.restore();\n  drawRain(now);\n  goalArrow(0,v,ME);goalArrow(1,v,OP);\n  // HUD\n  const cxm=W/2;\n  {const hg=c.createLinearGradient(0,0,0,92);hg.addColorStop(0,'rgba(8,9,25,.92)');hg.addColorStop(.75,'rgba(8,9,25,.75)');hg.addColorStop(1,'rgba(8,9,25,0)');c.fillStyle=hg;c.fillRect(0,0,W,92);\n   const bg2=c.createLinearGradient(0,HH-34,0,HH);bg2.addColorStop(0,'rgba(8,9,25,0)');bg2.addColorStop(1,'rgba(8,9,25,.85)');c.fillStyle=bg2;c.fillRect(0,HH-34,W,34)}\n  c.textAlign='center';c.font='400 34px \"Bagel Fat One\",system-ui,sans-serif';\n  c.fillStyle=ME;c.fillText(G.score[0],cxm-30,44);c.fillStyle='#9aa0d8';c.fillText('–',cxm,44);c.fillStyle=OP;c.fillText(G.score[1],cxm+30,44);\n  const tw=Math.min(180,W*.3),tot=G.pen?PEN_T:ROUND;bar(cxm-tw/2,54,tw,5,G.phase=='play'||G.phase=='ready'?Math.max(0,G.rt/tot):0,G.pen?GOLD:'#b69cff');\n  const bw=Math.max(60,Math.min(200,(W-tw-140)/2));\n  c.textAlign='left';c.font='800 12px Inter,system-ui,sans-serif';c.fillStyle=ME;c.fillText('TOI · '+SET.me.n.toUpperCase(),16,26);bar(16,34,bw,9,p0.en/100,ME);if(p0.yellow)card(16+bw+8,32);\n  c.textAlign='right';c.fillStyle=OP;c.fillText(SET.op.n.toUpperCase()+' · NIVEAU '+SET.op.lvl,W-62,26);bar(W-62-bw,34,bw,9,p1.en/100,OP,true);if(p1.yellow)card(W-62-bw-17,32);\n  c.textAlign='center';c.fillStyle='#9aa0d8';c.font='600 11px Inter,system-ui,sans-serif';c.fillText(SET.round+' · manche '+G.round+(G.pen?' · penalty':''),cxm,74);\n  if(!T.on||lastDev!='touch'){\n    c.font='600 12px Inter,system-ui,sans-serif';c.fillStyle='rgba(154,160,216,.8)';\n    c.fillText(lastDev=='pad'?'A : tir (maintenir) ou tacle · Y : lob · B : crochet · gâchettes : sprint · stick droit : effet · Start : pause':'Espace : tir (maintenir) ou tacle · I : lob · K : crochet · Maj : sprint · J / L : effet · Échap : pause',cxm,HH-14);\n  }\n  if(T.on){const h=p0.has?'TIR':'TACLE';if(bShootL.textContent!==h)bShootL.textContent=h}\n}\n\n// ---------- Écrans ----------\nconst $=id=>document.getElementById(id);\nfunction buildMenu(){\n  $('mT').textContent=SET.title;$('mSub').textContent=SET.round+' · duel en 1 contre 1 · premier à 3 buts';\n  $('nMe').textContent=SET.me.n;$('sMe').textContent=SET.me.club+' · Att '+SET.me.att+' · Déf '+SET.me.def+' · énergie '+Math.round(SET.me.en)+' %';\n  $('nOp').textContent=SET.op.n;$('sOp').textContent='Niveau '+SET.op.lvl;\n  $('swMe').style.background=`linear-gradient(135deg,${SET.me.a} 0 58%,${SET.me.b} 58% 100%)`;$('swOp').style.background=`linear-gradient(135deg,${SET.op.a} 0 58%,${SET.op.b} 58% 100%)`;\n}\nlet fi=-1;\nfunction show(id){for(const o of ['menu','pause','end'])$(o).hidden=o!==id;fi=-1;touchEl.hidden=!(id==null&&T.on);$('bPause').hidden=id!=null}\nfunction startGame(){newMatch();state='play';show(null);acc=0;prevB.shoot=true;prevB.lob=true}\nfunction setPause(v){state=v?'pause':'play';show(v?'pause':null)}\nfunction endMatch(){\n  state='end';const w=G.score[0]>G.score[1],S=G.stats;\n  G.res={win:w,score:G.score.slice(),rounds:G.round,downs:S.fouls[1],stats:JSON.parse(JSON.stringify(S))};try{H&&H.state&&H.state()}catch(e){}\n  $('endT').textContent=w?'Victoire':'Défaite';$('endT').style.color=w?'var(--me)':'var(--op)';\n  $('endS').textContent=`${G.score[0]} – ${G.score[1]} · ${SET.me.n} contre ${SET.op.n}`;\n  const row=(n,k)=>`<div>${n}</div><div style=\"color:var(--me);font-weight:800\">${S[k][0]}</div><div style=\"color:var(--op);font-weight:800\">${S[k][1]}</div>`;\n  $('endStats').innerHTML='<div class=\"h\">Statistiques</div><div class=\"h\">Toi</div><div class=\"h\">Adv.</div>'+row('Tirs','shots')+row('Lobs','lobs')+row('Arrêts','saves')+row('Tacles réussis','tackles')+row('Mises au sol','fouls')+row('Crochets','jinks');\n  show('end');\n}\n$('play').onclick=()=>{startGame();try{H&&H.state&&H.state()}catch(e){}};$('resume').onclick=()=>setPause(false);\n$('forfeit').onclick=()=>{if(!G)return;G.score[1]=Math.max(G.score[1],WIN);G.score[0]=Math.min(G.score[0],WIN-1);endMatch()};\n$('again').onclick=()=>{const r=G&&G.res;if(r&&H&&H.done)H.done(r)};\n// Pour la carrière : un duel est-il en cours ? Mise en pause quand l'onglet est quitté.\nwindow.duelOn=()=>state=='play'||state=='pause'||state=='end';\nwindow.autoPause=()=>{if(state=='play')setPause(true)};\nwindow.focusGame=()=>{try{window.focus()}catch(e){}};\n$('bPause').onclick=()=>{if(state=='play')setPause(true)};\nfunction navOverlay(){\n  const ov=['menu','pause','end'].map($).find(o=>!o.hidden);if(!ov)return;\n  const it=[...ov.querySelectorAll('[data-nav]')];if(!it.length)return;\n  if(IN.hnav)IN.nav=IN.hnav;\n  if(IN.nav){fi=fi<0?(state=='menu'?it.findIndex(x=>x.id=='play'):0):(fi+IN.nav+it.length)%it.length;it.forEach(x=>x.classList.remove('kf'));it[fi].classList.add('kf');it[fi].focus()}\n  if(IN.okDown){const el=fi>=0?it[fi]:(state=='menu'?$('play'):it[0]);el.click()}\n}\ndocument.addEventListener('pointerdown',()=>document.querySelectorAll('.kf').forEach(x=>x.classList.remove('kf')));\n\n// ---------- Boucle ----------\nlet last=performance.now(),acc=0;\nfunction frame(now){\n  const ft=Math.min(.05,(now-last)/1000);last=now;\n  readInput();\n  if(state=='play'){\n    if(IN.pauseDown)setPause(true);\n    else{\n      humanActions();\n      const sc=G.slow>0?.35:1;if(G.slow>0)G.slow-=ft;\n      acc+=ft*sc;let n=0;while(acc>=STEP&&n<20){step(STEP);acc-=STEP;n++;if(state!='play')break}\n    }\n  }else{\n    if(state=='pause'&&(IN.pauseDown||IN.backDown))setPause(false);\n    else navOverlay();\n  }\n  render(ft);\n  requestAnimationFrame(frame);\n}\nloadSetup();buildMenu();updPad();show('menu');\nrequestAnimationFrame(frame);\n})();\n</script>\n</body></html>\n";
